// Emit every generated file as path -> content (paths relative to generated/). Pure and deterministic.
import { createHash } from 'node:crypto';
import type { CapabilityDef, EventDef, Owned, Registry } from '../../../packages/contracts/src/index.ts';
import { agentVisible, autoRoute, mcpToolName } from './validate.ts';
import { canonical } from './canonical.ts';
import { pascal, tsType } from './schema-ts.ts';

const HEADER = '// GENERATED by tools/gen from manifests/. Do not edit. Run `node tools/gen/src/cli.ts` to regenerate.\n';
type Cap = Owned<CapabilityDef>;
type Files = Map<string, string>;

const json = (v: unknown) => canonical(v);
const q = (s: string) => JSON.stringify(s);
const capKey = (c: Cap) => `${c.name}${c.v > 1 ? `@${c.v}` : ''}`;
const slug = (s: string) => s.replace(/[^A-Za-z0-9._-]+/g, '_');

function latest(caps: Cap[]): Cap[] {
  const m = new Map<string, Cap>();
  for (const c of caps) { const p = m.get(c.name); if (!p || p.v < c.v) m.set(c.name, c); }
  return [...m.values()].sort((a, b) => (a.name < b.name ? -1 : 1));
}

interface Node { leaf?: string; kids: Map<string, Node> }

function tree(caps: Cap[]): Node {
  const root: Node = { kids: new Map() };
  for (const c of caps) {
    let n = root;
    for (const seg of c.name.split('.')) {
      let k = n.kids.get(seg);
      if (!k) { k = { kids: new Map() }; n.kids.set(seg, k); }
      n = k;
    }
    n.leaf = c.name;
  }
  return root;
}

function renderTree(n: Node, indent: number, leaf: (cap: string) => string): string {
  const pad = '  '.repeat(indent);
  const lines: string[] = [];
  for (const [k, kid] of [...n.kids.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    if (kid.leaf !== undefined) lines.push(`${pad}${k}: ${leaf(kid.leaf)},`);
    else lines.push(`${pad}${k}: {\n${renderTree(kid, indent + 1, leaf)}\n${pad}},`);
  }
  return lines.join('\n');
}

export function emitAll(reg: Registry): Files {
  const out: Files = new Map();
  const put = (p: string, c: string) => out.set(p, c);
  const caps = latest(reg.capabilities);
  const allCaps = reg.capabilities;
  const registryJson = json(reg);
  const hash = createHash('sha256').update(registryJson).digest('hex');

  put('README.md', '# generated\n\nEverything here is written by `tools/gen` from `manifests/`. Never edit by hand; run `node tools/gen/src/cli.ts` and commit the result. CI runs `--check` and fails on drift.\n');
  put('registry.json', registryJson);
  put('hash.txt', hash + '\n');
  put('registry.ts', `${HEADER}// Loads registry.json at runtime (no JSON module inference in the compiler).\nimport { readFileSync } from 'node:fs';\nimport type { Registry } from '../packages/contracts/src/registry.ts';\n\nexport const registry = JSON.parse(readFileSync(new URL('./registry.json', import.meta.url), 'utf8')) as Registry;\nexport const registryHash = ${q(hash)};\n`);

  // ---- types.ts: every input, output and event payload type
  {
    const lines: string[] = [HEADER, "export interface HandlerCtx { trace: { traceId: string; spanId?: string } }\n"];
    const map: string[] = [];
    for (const c of caps) {
      const n = pascal(c.name);
      lines.push(`export type ${n}In = ${tsType(c.input)};`);
      lines.push(`export type ${n}Out = ${tsType(c.output)};`);
      map.push(`  ${q(c.name)}: { in: ${n}In; out: ${n}Out };`);
    }
    lines.push('', 'export interface CapMap {', ...map, '}', '');
    const emap: string[] = [];
    for (const e of reg.events) {
      const n = pascal(e.name);
      lines.push(`export type ${n}Payload = ${tsType(e.payload)};`);
      emap.push(`  ${q(e.name)}: ${n}Payload;`);
    }
    lines.push('', 'export interface EventMap {', ...emap, '}', '');
    lines.push("export type CapName = keyof CapMap;", "export type EventName = keyof EventMap;", '');
    put('types.ts', lines.join('\n'));
  }

  // ---- client.ts and stubs.ts
  {
    const t = tree(caps);
    const versions = new Map(caps.map((c) => [c.name, c.v] as const));
    put('client.ts', `${HEADER}import type { CapMap } from './types.ts';

export interface CallOptions { traceId?: string; idempotencyKey?: string; signal?: AbortSignal }
export interface CallRequest { cap: keyof CapMap; v: number; input: unknown; opts?: CallOptions }
export type Transport = (req: CallRequest) => Promise<unknown>;

/** Typed client: one function per capability, bound to the latest contract version. */
export function createClient(transport: Transport) {
  const call = <C extends keyof CapMap>(cap: C, v: number) =>
    (input: CapMap[C]['in'], opts?: CallOptions): Promise<CapMap[C]['out']> =>
      transport({ cap, v, input, opts }) as Promise<CapMap[C]['out']>;
  return {
${renderTree(t, 2, (c) => `call(${q(c)}, ${versions.get(c)})`)}
  };
}

export type Client = ReturnType<typeof createClient>;
`);
    put('stubs.ts', `${HEADER}// Module call stubs (boundary B1): modules call other modules through these typed wrappers around ctx.call.
import type { CapMap } from './types.ts';
import type { CallOptions } from './client.ts';

export interface CallCtx {
  call<C extends keyof CapMap>(cap: C, input: CapMap[C]['in'], opts?: CallOptions): Promise<CapMap[C]['out']>;
}

export function stubs(ctx: CallCtx) {
  const call = <C extends keyof CapMap>(cap: C) =>
    (input: CapMap[C]['in'], opts?: CallOptions): Promise<CapMap[C]['out']> => ctx.call(cap, input, opts);
  return {
${renderTree(t, 2, (c) => `call(${q(c)})`)}
  };
}
`);
  }

  // ---- routes.ts, cli.ts
  {
    const routes = allCaps.map((c) => {
      const r = autoRoute(c);
      return {
        method: r.method, path: r.path, cap: c.name, v: c.v, module: c.module, effects: c.effects, permission: c.permission, level: c.level,
        resource: c.resource, idempotency: c.idempotency, risk: c.risk, offline: c.offline ?? null, teamOnly: c.teamOnly ?? false, gate: c.gate?.act ?? null,
      };
    }).sort((a, b) => (a.path + a.method < b.path + b.method ? -1 : 1));
    put('routes.ts', `${HEADER}import type { ResourceBinding } from '../packages/contracts/src/types.ts';

export interface Route {
  method: string; path: string; cap: string; v: number; module: string;
  effects: 'read' | 'write' | 'outward'; permission: string | null; level: 'view' | 'use' | 'edit' | 'manage';
  resource: ResourceBinding; idempotency: 'key' | 'natural' | 'none'; risk: 'low' | 'medium' | 'high';
  offline: 'patch' | 'queue' | 'online' | null; teamOnly: boolean; gate: string | null;
}

export const routes: Route[] = ${JSON.stringify(routes, null, 2)};
`);
    const cli = allCaps.filter((c) => c.surfaces.cli).map((c) => ({ command: c.surfaces.cli as string, cap: c.name, v: c.v })).sort((a, b) => (a.command < b.command ? -1 : 1));
    put('cli.ts', `${HEADER}export const cliCommands: Array<{ command: string; cap: string; v: number }> = ${JSON.stringify(cli, null, 2)};\n`);
  }

  // ---- per-module server glue
  const modIds = reg.modules.map((m) => m.id);
  for (const id of modIds) {
    const mc = latest(allCaps.filter((c) => c.module === id));
    if (!mc.length) continue;
    const lines = [
      HEADER,
      "import type { CapMap, HandlerCtx } from '../../types.ts';",
      '',
      'export type Handler<C extends keyof CapMap, X extends HandlerCtx = HandlerCtx> = (ctx: X, input: CapMap[C][\'in\']) => Promise<CapMap[C][\'out\']>;',
      '',
      'export interface Handlers<X extends HandlerCtx = HandlerCtx> {',
      ...mc.map((c) => `  ${q(c.name)}: Handler<${q(c.name)}, X>;`),
      '}',
      '',
    ];
    put(`modules/${id}/handlers.ts`, lines.join('\n'));
    put(`modules/${id}/not-implemented.ts`, `${HEADER}import { VyreErr, notImplemented } from '../../../packages/contracts/src/errors.ts';
import type { HandlerCtx } from '../../types.ts';
import type { Handlers } from './handlers.ts';

/** Served while the module is a stub and no example answer is wanted: every capability fails with a typed error carrying the trace id. */
export const handlers: Handlers<HandlerCtx> = {
${mc.map((c) => `  ${q(c.name)}: async (ctx) => { throw new VyreErr(notImplemented(${q(c.name)}, ctx.trace)); },`).join('\n')}
};
`);
    put(`modules/${id}/stub-impl.ts`, `${HEADER}import type { HandlerCtx } from '../../types.ts';
import type { Handlers } from './handlers.ts';

/** Example answers: the first example output of each capability (used when the host serves a stub module). */
export const handlers: Handlers<HandlerCtx> = {
${mc.map((c) => `  ${q(c.name)}: async () => (${JSON.stringify(c.examples[0]?.output ?? {})} as unknown) as never,`).join('\n')}
};
`);
  }

  // ---- MCP tools
  {
    const byCap = new Map(caps.map((c) => [c.name, c] as const));
    const tools: unknown[] = [];
    for (const c of caps) {
      const name = mcpToolName(c);
      if (!name || !agentVisible(c)) continue;
      const a = c.surfaces.agent;
      const planMode = typeof a === 'object' ? a.planMode : c.effects === 'read' ? 'allowed' : 'blocked';
      tools.push({ name, description: c.summary, inputSchema: c.input, toolset: c.surfaces.mcp?.toolset, deferred: c.surfaces.mcp?.deferred ?? false, cap: c.name, v: c.v, effects: c.effects, planMode, blocks: typeof a === 'object' ? a.blocks ?? [] : [] });
    }
    const have = new Set(tools.map((x) => (x as { name: string }).name));
    for (const t of reg.agentTools) {
      if (have.has(t.name)) continue;
      const backing = t.cap ? byCap.get(t.cap) : undefined;
      tools.push({ name: t.name, description: t.summary, inputSchema: t.input, toolset: backing?.surfaces.mcp?.toolset ?? 'meta', deferred: t.deferred ?? false, cap: t.cap ?? null, v: backing?.v ?? 1, effects: t.effects, planMode: t.planMode, blocks: t.blocks ?? [], local: t.local ?? 'none' });
    }
    tools.sort((a, b) => ((a as { name: string }).name < (b as { name: string }).name ? -1 : 1));
    put('mcp-tools.json', json({ tools }));
    const index = (tools as Array<{ name: string; description: string; toolset: string; deferred: boolean }>).map((t) => ({ name: t.name, summary: t.description, toolset: t.toolset, deferred: t.deferred }));
    put('tool-index.json', json({ tools: index }));
    put('tools.ts', `${HEADER}import { readFileSync } from 'node:fs';

export interface AgentTool { name: string; description: string; inputSchema: unknown; toolset: string; deferred: boolean; cap: string | null; v: number; effects: 'read' | 'write' | 'outward'; planMode: 'allowed' | 'blocked'; blocks: string[]; local?: string }

export const tools = (JSON.parse(readFileSync(new URL('./mcp-tools.json', import.meta.url), 'utf8')) as { tools: AgentTool[] }).tools;
`);
  }

  // ---- catalogues
  put('permissions.ts', `${HEADER}import { registry } from './registry.ts';

export type PermissionKeyName = ${reg.permissions.map((p) => q(p.key)).join(' | ') || 'never'};

export const permissions = registry.permissions;
export const roleDefaults: Record<string, Record<string, boolean>> = Object.fromEntries(
  registry.permissions.map((p) => [p.key, p.defaults as Record<string, boolean>]),
);
`);
  put('events.ts', `${HEADER}import { registry } from './registry.ts';

export type EventNameLiteral = ${reg.events.map((e) => q(e.name)).join(' | ') || 'never'};

export const events = registry.events;
/** Events usable as Automation triggers (the trigger palette). */
export const triggerEvents = registry.events.filter((e) => e.trigger);
`);
  put('kinds.ts', `${HEADER}import { registry } from './registry.ts';

export const gateActs = registry.gateActs;
export const taskKinds = registry.taskKinds;
export const notificationKinds = registry.notificationKinds;
export const healthChecks = registry.health;
export const retention = registry.retention;
export const settings = registry.settings;
export const importSources = registry.importSources;
export const blocks = registry.blocks;
export const lists = registry.lists;
`);
  put('errors.ts', `${HEADER}export type KnownErrorCode = ${reg.errors.map((e) => q(e.code)).join(' | ')};\n`);

  // ---- tests
  for (const id of modIds) {
    const mc = latest(allCaps.filter((c) => c.module === id));
    for (const c of allCaps.filter((x) => x.module === id)) {
      const hasStub = mc.some((x) => x.name === c.name && x.v === c.v);
      put(`tests/${id}/${slug(c.name)}${c.v > 1 ? `.v${c.v}` : ''}.contract.test.ts`, `${HEADER}import { capabilityContract } from '../../../packages/contracts/src/contract-check.ts';
import { registry } from '../../registry.ts';
${hasStub ? `import { handlers } from '../../modules/${id}/not-implemented.ts';\nimport { handlers as examples } from '../../modules/${id}/stub-impl.ts';\n` : ''}
capabilityContract(registry, ${q(c.name)}, ${c.v}${hasStub ? `, handlers[${q(c.name)}], examples[${q(c.name)}]` : ''});
`);
    }
    if (reg.events.some((e) => e.module === id)) {
      put(`tests/${id}/events.contract.test.ts`, `${HEADER}import { eventContracts } from '../../../packages/contracts/src/contract-check.ts';
import { registry } from '../../registry.ts';

eventContracts(registry, ${q(id)});
`);
    }
  }

  // ---- docs
  emitDocs(reg, put, caps);
  return out;
}

function fence(lang: string, body: string): string {
  return '```' + lang + '\n' + body + '\n```';
}

function capDoc(c: Cap): string {
  const r = autoRoute(c);
  const res = 'create' in c.resource ? `${c.resource.type} (create under ${c.resource.parent})` : 'id' in c.resource ? `${c.resource.type} (${c.resource.id})` : 'space';
  const s = c.surfaces;
  return [
    `# ${c.name}`, '', c.summary, '',
    '| | |', '|---|---|',
    `| Module | ${c.module} |`,
    `| Version | ${c.v} (since ${c.since}) |`,
    `| Effects | ${c.effects} |`,
    `| Permission | ${c.permission ?? 'grant only'} |`,
    `| Grant level | ${c.level} |`,
    `| Risk | ${c.risk} |`,
    `| Resource | ${res} |`,
    `| Gate | ${c.gate ? c.gate.act + (c.gate.when ? ` when ${c.gate.when}` : '') : 'none'} |`,
    `| Idempotency | ${c.idempotency} |`,
    `| Offline | ${c.offline ?? 'online'} |`,
    `| Audit | ${c.audit ?? 'none'} |`,
    `| Team Space only | ${c.teamOnly ? 'yes' : 'no'} |`,
    `| HTTP | ${r.method} ${r.path} |`,
    `| MCP tool | ${s.mcp ? `${mcpToolName(c)} (${s.mcp.toolset}${s.mcp.deferred ? ', deferred' : ''})` : 'none'} |`,
    `| CLI | ${s.cli ?? 'none'} |`,
    `| Emits | ${c.emits.length ? c.emits.join(', ') : 'none'} |`,
    '', '## Input', '', fence('ts', `type In = ${tsType(c.input)};`),
    '', '## Output', '', fence('ts', `type Out = ${tsType(c.output)};`),
    '', '## Errors', '', ...c.errors.map((e) => `- ${e}`),
    '', '## Example', '', fence('json', JSON.stringify(c.examples[0], null, 2)), '',
  ].join('\n');
}

function eventDoc(e: Owned<EventDef>): string {
  return [
    `# ${e.name}`, '', e.summary, '',
    '| | |', '|---|---|',
    `| Module | ${e.module} |`, `| Schema version | ${e.sv} |`, `| Subject | ${e.subject.type} at ${e.subject.id} |`,
    `| Visibility | ${e.vis} |`, `| Label | ${e.label ?? 'none'} |`, `| Replay | ${e.replay} |`,
    `| Automation trigger | ${e.trigger ? e.trigger.title : 'no'} |`, `| Notification | ${e.notify ?? 'none'} |`, `| Retention | ${e.retention ?? 'default'} |`,
    '', '## Payload', '', fence('ts', `type Payload = ${tsType(e.payload)};`), '',
  ].join('\n');
}

function emitDocs(reg: Registry, put: (p: string, c: string) => void, caps: Cap[]): void {
  for (const c of reg.capabilities) put(`docs/capabilities/${slug(c.name)}${c.v > 1 ? `.v${c.v}` : ''}.md`, capDoc(c));
  for (const e of reg.events) put(`docs/events/${slug(e.name)}.md`, eventDoc(e));
  for (const p of reg.permissions) {
    put(`docs/permissions/${slug(p.key)}.md`, [
      `# ${p.key}`, '', p.title, '', `Area: ${p.area}. Risk: ${p.risk}. Applies to: ${p.appliesTo.join(', ')}.`, '',
      '| Role | Default |', '|---|---|', ...['owner', 'admin', 'developer', 'member', 'guest'].map((r) => `| ${r} | ${p.defaults[r] ? 'on' : 'off'} |`),
      '', '## Capabilities that need it', '', ...(reg.capabilities.filter((c) => c.permission === p.key).map((c) => `- ${c.name}`)), '',
    ].join('\n'));
  }
  for (const e of reg.errors) {
    put(`docs/errors/${slug(e.code)}.md`, [`# ${e.code}`, '', e.summary, '', `HTTP ${e.http}. Retryable: ${e.retryable ? 'yes' : 'no'}.`, '',
      '## Raised by', '', ...(reg.capabilities.filter((c) => c.errors.includes(e.code)).slice(0, 25).map((c) => `- ${c.name}`)), ''].join('\n'));
  }
  for (const c of reg.connectors) {
    put(`docs/connectors/${slug(c.key)}.md`, [
      `# ${c.title}`, '', `Key ${c.key}, module ${c.module}. Mode ${c.mode}, owned by a ${c.scope}. Auth ${c.auth.type}.`, '',
      '## Egress domains', '', ...c.domains.map((d) => `- ${d}`), '',
      '## Secrets (names only)', '', ...c.secrets.map((s) => `- ${s.name}: ${s.description}`), '',
      '## Webhook sources', '', ...(c.sources ?? []).map((s) => `- ${s.path} (${s.verify}) emits ${s.event}`), '',
      '## Actions', '', ...(c.actions ?? []).map((a) => `- ${a}`), '',
      '## Synced types', '', ...(c.syncedTypes ?? []).map((s) => `- ${s.type} from ${s.remote}`), '',
    ].join('\n'));
  }
  // module pages and lane briefs
  const lanes = [...new Set(reg.modules.map((m) => m.owner))].sort();
  for (const m of reg.modules) {
    const mc = reg.capabilities.filter((c) => c.module === m.id);
    const me = reg.events.filter((e) => e.module === m.id);
    put(`docs/modules/${m.id}.md`, [
      `# ${m.title} (${m.id})`, '', `Lane ${m.owner}. Kind ${m.kind}. Status ${m.status}. Version ${m.version}.`, '',
      `Requires: ${m.requires.length ? m.requires.join(', ') : 'nothing'}.`, '',
      `## Capabilities (${mc.length})`, '', ...mc.map((c) => `- [${c.name}](../capabilities/${slug(c.name)}${c.v > 1 ? `.v${c.v}` : ''}.md): ${c.summary}`),
      '', `## Events (${me.length})`, '', ...me.map((e) => `- [${e.name}](../events/${slug(e.name)}.md): ${e.summary}`), '',
    ].join('\n'));
  }
  for (const lane of lanes) {
    const ms = reg.modules.filter((m) => m.owner === lane);
    const lines = [`# Lane ${lane}: brief skeleton`, '', 'Generated from the manifests. The lead completes it by hand (spec sections, reused 0.6 files, traps, first two hours).', '', '## Modules', ''];
    for (const m of ms) {
      const mc = reg.capabilities.filter((c) => c.module === m.id);
      const me = reg.events.filter((e) => e.module === m.id);
      lines.push(`### ${m.id}`, '', `Capabilities to implement: ${mc.length}. Events to emit: ${me.length}. Contract tests that must go green: \`generated/tests/${m.id}/\`.`, '',
        'Capabilities:', ...mc.map((c) => `- ${c.name} (${c.effects}, ${c.permission ?? 'grant only'}, level ${c.level}${c.gate ? `, gate ${c.gate.act}` : ''})`), '',
        'Events:', ...me.map((e) => `- ${e.name}`), '');
    }
    put(`docs/lanes/${lane}.md`, lines.join('\n'));
  }
  const count = (xs: unknown[]) => xs.length;
  put('docs/index.md', [
    '# Reference index', '',
    '| Kind | Count |', '|---|---|',
    `| Modules | ${reg.modules.filter((m) => m.kind === 'module').length} |`,
    `| Connector manifests | ${reg.modules.filter((m) => m.kind === 'connector').length} |`,
    `| Kit manifests | ${reg.modules.filter((m) => m.kind === 'kit').length} |`,
    `| Capabilities | ${count(caps)} |`, `| Events | ${count(reg.events)} |`, `| Permissions | ${count(reg.permissions)} |`,
    `| Entities | ${count(reg.entities)} |`, `| Record types | ${count(reg.recordTypes)} |`, `| Field types | ${count(reg.fieldTypes)} |`,
    `| View kinds | ${count(reg.viewKinds)} |`, `| Steps | ${count(reg.steps)} |`, `| Triggers | ${count(reg.triggers)} |`,
    `| Connectors | ${count(reg.connectors)} |`, `| Agent tools (not 1:1 with a capability) | ${count(reg.agentTools)} |`, `| Block types | ${count(reg.blocks)} |`,
    `| Screens | ${count(reg.screens)} |`, `| Health checks | ${count(reg.health)} |`, `| Gate act kinds | ${count(reg.gateActs)} |`,
    `| Task kinds | ${count(reg.taskKinds)} |`, `| Notification kinds | ${count(reg.notificationKinds)} |`, `| Import sources | ${count(reg.importSources)} |`,
    `| Settings | ${count(reg.settings)} |`, `| Retention defaults | ${count(reg.retention)} |`, `| Lists | ${count(reg.lists)} |`,
    `| Error codes | ${count(reg.errors)} |`, '',
    '## Modules', '', ...reg.modules.map((m) => `- [${m.id}](modules/${m.id}.md) (${m.owner}, ${m.kind})`), '',
  ].join('\n'));
}

export function summary(reg: Registry): string {
  const rows: Array<[string, number]> = [
    ['modules', reg.modules.filter((m) => m.kind === 'module').length], ['connector manifests', reg.modules.filter((m) => m.kind === 'connector').length],
    ['kit manifests', reg.modules.filter((m) => m.kind === 'kit').length], ['capabilities', latest(reg.capabilities).length], ['events', reg.events.length],
    ['permissions', reg.permissions.length], ['entities', reg.entities.length], ['recordTypes', reg.recordTypes.length], ['fieldTypes', reg.fieldTypes.length],
    ['viewKinds', reg.viewKinds.length], ['steps', reg.steps.length], ['triggers', reg.triggers.length], ['connectors', reg.connectors.length],
    ['agentTools', reg.agentTools.length], ['blocks', reg.blocks.length], ['screens', reg.screens.length], ['health', reg.health.length],
    ['gateActs', reg.gateActs.length], ['taskKinds', reg.taskKinds.length], ['notificationKinds', reg.notificationKinds.length],
    ['importSources', reg.importSources.length], ['settings', reg.settings.length], ['retention', reg.retention.length], ['lists', reg.lists.length],
    ['errorCodes', reg.errors.length],
  ];
  const per = reg.modules.map((m) => `${m.id}: caps=${reg.capabilities.filter((c) => c.module === m.id).length} events=${reg.events.filter((e) => e.module === m.id).length}`);
  return ['COUNTS', ...rows.map(([k, n]) => `${k}=${n}`), 'PER-MODULE', ...per].join('\n');
}
